<?php
 namespace QQWorld\Reports\Test\Unit\Controller\Adminhtml\Report\Product; use QQWorld\Reports\Controller\Adminhtml\Report\Product\Sold; use QQWorld\Framework\DataObject; use QQWorld\Framework\Phrase; class SoldTest extends \QQWorld\Reports\Test\Unit\Controller\Adminhtml\Report\AbstractControllerTest { protected $sold; protected $dateMock; protected function setUp() { parent::setUp(); $this->dateMock = $this->getMockBuilder(\QQWorld\Framework\Stdlib\DateTime\Filter\Date::class) ->disableOriginalConstructor() ->getMock(); $objectManager = new \QQWorld\Framework\TestFramework\Unit\Helper\ObjectManager($this); $this->sold = $objectManager->getObject( \QQWorld\Reports\Controller\Adminhtml\Report\Product\Sold::class, [ 'context' => $this->contextMock, 'fileFactory' => $this->fileFactoryMock, 'dateFilter' => $this->dateMock, ] ); } public function testExecute() { $titleMock = $this->getMockBuilder(\QQWorld\Framework\View\Page\Title::class) ->disableOriginalConstructor() ->getMock(); $titleMock ->expects($this->once()) ->method('prepend') ->with(new Phrase('Ordered Products Report')); $this->viewMock ->expects($this->once()) ->method('getPage') ->willReturn( new DataObject( ['config' => new DataObject( ['title' => $titleMock] )] ) ); $this->menuBlockMock ->expects($this->once()) ->method('setActive') ->with('QQWorld_Reports::report_products_sold'); $this->breadcrumbsBlockMock ->expects($this->exactly(3)) ->method('addLink') ->withConsecutive( [new Phrase('Reports'), new Phrase('Reports')], [new Phrase('Products'), new Phrase('Products')], [new Phrase('Products Ordered'), new Phrase('Products Ordered')] ); $this->sold->execute(); } } 